{'filename': 'frontend/apps/app/features/projects/components/ProjectItem/LastCommitData.tsx', 'status': 'added', 'patch': "@@ -0,0 +1,30 @@
+'use server'
+
+import { getLastCommit } from '@liam-hq/github'
+
+// サーバーアクションとしてデータ取得関数を定義
+export async function fetchLastCommitData(
+ installationId: number,
+ owner: string,
+ repo: string,
+) {
+ try {
+ if (!installationId || !owner || !repo) {
+ return null
+ }
+
+ const commitInfo = await getLastCommit(installationId, owner, repo)
+
+ if (commitInfo) {
+ return {
+ author: commitInfo.author,
+ date: commitInfo.date,
+ }
+ }
+
+ return null
+ } catch (error) {
+ console.error('Failed to fetch last commit info:', error)
+ return null
+ }
+}"},{'filename': 'frontend/apps/app/features/projects/components/ProjectItem/LastCommitDataWrapper.tsx', 'status': 'added', 'patch': "@@ -0,0 +1,75 @@
+'use client'
+
+import { useEffect, useState } from 'react'
+import { fetchLastCommitData } from './LastCommitData'
+
+interface LastCommitDataWrapperProps {
+ installationId: number
+ owner: string
+ repo: string
+ defaultDate: string
+}
+
+interface CommitInfo {
+ author: string
+ date: string
+}
+
+export function LastCommitDataWrapper({
+ installationId,
+ owner,
+ repo,
+ defaultDate,
+}: LastCommitDataWrapperProps) {
+ const [commitInfo, setCommitInfo] = useState<CommitInfo | null>(null)
+ const [isLoading, setIsLoading] = useState(true)
+
+ // 日付のフォーマット関数
+ const formatDate = (dateString: string) => {
+ const date = new Date(dateString)
+ return date.toLocaleDateString('en-US', {
+ month: 'short',
+ day: 'numeric',
+ year: 'numeric',
+ })
+ }
+
+ useEffect(() => {
+ async function loadData() {
+ try {
+ const data = await fetchLastCommitData(installationId, owner, repo)
+ setCommitInfo(data)
+ } catch (error) {
+ console.error('Error fetching commit data:', error)
+ } finally {
+ setIsLoading(false)
+ }
+ }
+
+ loadData()
+ }, [installationId, owner, repo])
+
+ if (isLoading) {
+ return <span>Loading commit info...</span>
+ }
+
+ // コミット情報が取得できた場合
+ if (commitInfo) {
+ return (
+ <>
+ <span>{commitInfo.author}</span>
+ <span>committed</span>
+ <span>on {formatDate(commitInfo.date)}</span>
+ </>
+ )
+ }
+
+ // デフォルト表示（取得失敗時）
+ return (
+ <>
+ <span>User</span>
+ <span>committed</span>
+ <span>on {formatDate(defaultDate)}</span>
+ </>
+ )
+}"},{'filename': 'frontend/apps/app/features/projects/components/ProjectItem/OrganizationData.tsx', 'status': 'added', 'patch': "@@ -0,0 +1,45 @@
+'use server'
+
+import { getOrganizationInfo } from '@liam-hq/github'
+import { OrganizationIcon } from './OrganizationIcon'
+import { ProjectIcon } from './ProjectIcon'
+import styles from './ProjectItem.module.css'
+
+interface OrganizationDataProps {
+ installationId: number
+ owner: string
+ repo: string
+}
+
+// サーバーアクションとしてデータ取得関数を分離
+export async function fetchOrganizationData(
+ installationId: number,
+ owner: string,
+ repo: string,
+) {
+ try {
+ if (!installationId || !owner || !repo) {
+ return null
+ }
+ const orgInfo = await getOrganizationInfo(installationId, owner, repo)
+ return orgInfo?.avatar_url || null
+ } catch (error) {
+ console.error('Failed to fetch organization info:', error)
+ return null
+ }
+}
+
+// サーバーコンポーネント
+export async function OrganizationData({
+ installationId,
+ owner,
+ repo,
+}: OrganizationDataProps) {
+ const avatarUrl = await fetchOrganizationData(installationId, owner, repo)
+
+ if (avatarUrl) {
+ return <OrganizationIcon avatarUrl={avatarUrl} owner={owner} />
+ }
+
+ return <ProjectIcon className={styles.projectIcon} />
+}"},{'filename': 'frontend/apps/app/features/projects/components/ProjectItem/OrganizationDataWrapper.tsx', 'status': 'added', 'patch': "@@ -0,0 +1,47 @@
+'use client'
+
+import { useEffect, useState } from 'react'
+import { fetchOrganizationData } from './OrganizationData'
+import { OrganizationIcon } from './OrganizationIcon'
+import { ProjectIcon } from './ProjectIcon'
+import styles from './ProjectItem.module.css'
+
+interface OrganizationDataWrapperProps {
+ installationId: number
+ owner: string
+ repo: string
+}
+
+export function OrganizationDataWrapper({
+ installationId,
+ owner,
+ repo,
+}: OrganizationDataWrapperProps) {
+ const [avatarUrl, setAvatarUrl] = useState<string | null>(null)
+ const [isLoading, setIsLoading] = useState(true)
+
+ useEffect(() => {
+ async function loadData() {
+ try {
+ const data = await fetchOrganizationData(installationId, owner, repo)
+ setAvatarUrl(data)
