+ console.error('Error fetching organization data:', error)
+ } finally {
+ setIsLoading(false)
+ }
+ }
+
+ loadData()
+ }, [installationId, owner, repo])
+
+ if (isLoading) {
+ return <ProjectIcon className={styles.projectIcon} />
+ }
+
+ return avatarUrl ? (
+ <OrganizationIcon avatarUrl={avatarUrl} owner={owner} />
+ ) : (
+ <ProjectIcon className={styles.projectIcon} />
+ )
+}"},{'filename': 'frontend/apps/app/features/projects/components/ProjectItem/OrganizationIcon.tsx', 'status': 'modified', 'patch': "@@ -1,35 +1,25 @@
